type Copy = { [K in keyof typeof copy.zh]: string };

const roleInfo = {
  platform: { icon: Laptop, color: 'from-[#0071e3] to-[#5a7fff]' },
  culture: { icon: Landmark, color: 'from-[#7a4b27] to-[#b78552]' },
  organizer: { icon: Building2, color: 'from-[#7c5be0] to-[#ae78ea]' },
  police: { icon: ShieldCheck, color: 'from-[#006f65] to-[#17a386]' }
};

function getRoleName(t: Copy, role: RoleId) {
  return ({ platform: t.rolePlatform, culture: t.roleCulture, organizer: t.roleOrganizer, police: t.rolePolice })[role];
}
function getRoleSub(t: Copy, role: RoleId) {
  return ({ platform: t.rolePlatformSub, culture: t.roleCultureSub, organizer: t.roleOrganizerSub, police: t.rolePoliceSub })[role];
}
function roleViewTag(t: Copy, role: RoleId) {
  return ({ platform: t.platformView, culture: t.cultureView, organizer: t.organizerView, police: t.policeView })[role];
}
function statusLabel(t: Copy, status: CoserSubmission['auditStatus']) {
  return ({ pending: t.statusPending, approved: t.approved, flagged: t.statusFlagged, rejected: t.statusRejected })[status];
}
function eventStatusLabel(t: Copy, status: EventRecord['status']) {
  return ({ draft: t.statusDraft, pending: t.statusPending, published: t.statusPublished, ended: t.statusEnded })[status];
}

function AppLogo() {
  return <div className="relative w-9 h-9 rounded-[12px] bg-gradient-to-br from-[#0071e3] to-[#6e5ce6] shadow-[0_7px_16px_rgba(0,113,227,0.25)] flex items-center justify-center overflow-hidden"><div className="absolute -top-1 -right-1 w-5 h-5 rounded-full bg-white/20" /><Sparkles className="relative w-[18px] h-[18px] text-white" strokeWidth={2.5} /></div>;
}

function Brand({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-center gap-2.5"><AppLogo />{!compact && <div className="leading-tight"><div className="font-semibold text-[16px] tracking-[-0.04em]">趣集</div><div className="text-[12px] text-[#707075] mt-0.5">文化活动协同平台</div></div>}</div>;
}

function SmallLabel({ children }: { children: ReactNode }) {
  return <span className="text-[12px] font-semibold tracking-[0.04em] text-[#6e6e73]">{children}</span>;
}

function LineText({ lines, className = '' }: { lines: string[]; className?: string }) {
  return <span className={`block ${className}`}>{lines.map((line, index) => <span key={line} className="block">{line}{index < lines.length - 1 ? <br /> : null}</span>)}</span>;
}

function LanguageSwitch({ lang, setLang, minimal = false }: { lang: Language; setLang: (lang: Language) => void; minimal?: boolean }) {
  const labels: { id: Language; text: string }[] = [{ id: 'zh', text: '中文' }, { id: 'en', text: 'EN' }, { id: 'ug', text: 'ئۇيغۇرچە' }];
  return <div className={`flex items-center rounded-full bg-white/90 border border-black/[0.08] p-1 shadow-[0_2px_8px_rgba(0,0,0,0.04)] ${minimal ? '' : ''}`} aria-label="Language switcher">{labels.map(item => <button key={item.id} onClick={() => setLang(item.id)} className={`h-7 px-2.5 rounded-full text-[12px] font-medium transition-all ${lang === item.id ? 'bg-[#1d1d1f] text-white shadow-sm' : 'text-[#4f4f54] hover:bg-[#f0f0f2]'}`}>{item.text}</button>)}</div>;
}

